const OPERATORS = new Set(['+', '-', '*', '/', '%', '^']);
const NAME_START = /[A-Za-z_]/;
const NAME_CONT = /[A-Za-z0-9_]/;
const DIGIT = /[0-9]/;
const NUMBER_STRICT = /^(\d+(\.\d+)?|\.\d+)([eE][+-]?\d+)?$/;

/**
 * Split an expression into tokens.
 *
 * @param {string} input expression source
 * @returns {{ type: 'number' | 'name' | 'operator' | 'lparen' | 'rparen' | 'comma', value: number | string, index: number }[]}
 *   tokens in source order
 */
export function tokenize(input) {
  const tokens = [];
  const len = input.length;
  let i = 0;

  while (i < len) {
    const c = input[i];

    if (c === ' ' || c === '\t' || c === '\n' || c === '\r' || c === '\f' || c === '\v') {
      i += 1;
      continue;
    }

    if (DIGIT.test(c) || (c === '.' && DIGIT.test(input[i + 1] ?? ''))) {
      const start = i;
      let j = i;
      while (j < len) {
        const cj = input[j];
        if (DIGIT.test(cj) || NAME_START.test(cj) || cj === '.') {
          j += 1;
          continue;
        }
        if ((cj === '+' || cj === '-') && (input[j - 1] === 'e' || input[j - 1] === 'E')) {
          j += 1;
          continue;
        }
        break;
      }
      const text = input.slice(start, j);
      if (!NUMBER_STRICT.test(text)) {
        throw new ExprError(`malformed number at ${start}`, start);
      }
      tokens.push({ type: 'number', value: Number(text), index: start });
      i = j;
      continue;
    }

    if (NAME_START.test(c)) {
      const start = i;
      let j = i + 1;
      while (j < len && NAME_CONT.test(input[j])) j += 1;
      tokens.push({ type: 'name', value: input.slice(start, j), index: start });
      i = j;
      continue;
    }

    if (OPERATORS.has(c)) {
      tokens.push({ type: 'operator', value: c, index: i });
      i += 1;
      continue;
    }

    if (c === '(') {
      tokens.push({ type: 'lparen', value: c, index: i });
      i += 1;
      continue;
    }

