/**
 * Parse an expression into a tree.
 *
 * @param {string} input expression source
 * @returns {object} the expression tree; parentheses leave no node behind
 */
export function parse(input) {
  const tokens = tokenize(input);
  const len = input.length;
  let pos = 0;

  const peek = () => tokens[pos];
  const advance = () => tokens[pos++];

  const unexpectedEnd = () => new ExprError(`unexpected end of input at ${len}`, len);
  const unexpectedToken = (tok) => new ExprError(`unexpected token '${tok.value}' at ${tok.index}`, tok.index);

  function parsePrimary() {
    const tok = peek();
    if (!tok) throw unexpectedEnd();

    if (tok.type === 'number') {
      advance();
      return { type: 'number', value: tok.value, index: tok.index };
    }

    if (tok.type === 'name') {
      advance();
      const nameEnd = tok.index + tok.value.length;
      const next = peek();
      if (next && next.type === 'lparen' && next.index === nameEnd) {
        advance(); // consume '('
        const args = [];
        let cur = peek();
        if (cur && cur.type === 'rparen') {
          advance();
        } else {
          for (;;) {
            args.push(parseAdditive());
            cur = peek();
            if (!cur) throw unexpectedEnd();
            if (cur.type === 'comma') {
              advance();
              continue;
            }
            if (cur.type === 'rparen') {
              advance();
              break;
            }
            throw unexpectedToken(cur);
          }
        }
        return { type: 'call', name: tok.value, args, index: tok.index };
      }
      return { type: 'variable', name: tok.value, index: tok.index };
    }

    if (tok.type === 'lparen') {
      advance();
      const inner = parseAdditive();
      const cur = peek();
      if (cur && cur.type === 'rparen') {
        advance();
        return inner;
      }
      if (cur) throw new ExprError(`missing closing parenthesis at ${cur.index}`, cur.index);
      throw new ExprError(`missing closing parenthesis at ${len}`, len);
    }

    throw unexpectedToken(tok);
  }

  function parsePower() {
    const left = parsePrimary();
    const tok = peek();
    if (tok && tok.type === 'operator' && tok.value === '^') {
      advance();
      const right = parseUnary();
      return { type: 'binary', op: '^', left, right, index: tok.index };
    }
    return left;
  }

